def active_component_rows(
    rows,
    *,
    is_retired_component_type=_default_is_retired_component_type,
    programme_deleted_row,
):
    return [
        row for row in rows
        if not is_retired_component_type(row.get('type'))
        and not programme_deleted_row(row)
    ]

